1	const PAYMENT_LABELS = { pix: 'PIX', credit_card: 'Cartão', debit_card: 'Débito', cash: 'Dinheiro' };
2	
3	const printIframe = (html, id) => {
4	  const f = document.createElement('iframe');
5	  f.id = id; f.style.cssText = 'position:fixed;bottom:-1px;left:-1px;width:1px;height:1px;border:0;opacity:0;pointer-events:none';
6	  document.body.appendChild(f);
7	  try { f.contentDocument.open(); f.contentDocument.write(html); f.contentDocument.close(); }
8	  catch { f.remove(); const w = window.open('', '_blank'); if (w) { w.document.write(html); w.document.close(); } }
9	};
