11	export const printFichaMotoboy = (pedido, itens, cliente, restauranteNome) => {
12	  const addr = cliente?.address_json ?? {};
13	  const rua = [addr.logradouro, addr.numero].filter(Boolean).join(', ');
14	  const compl = [addr.complemento, addr.bairro].filter(Boolean).join(' — ');
15	  const cidade = [addr.cidade, addr.estado].filter(Boolean).join(' / ');
16	  const ref = addr.referencia ?? '';
17	  const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
18	  const hora = new Date(pedido.created_at).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
19	  const pgto = PAYMENT_LABELS[pedido.payment_method] ?? pedido.payment_method;
20	  const isCash = pedido.payment_method === 'cash';
21	  const bc = barcodeValue(pedido.id);
22	  const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Ficha Motoboy #${pedido.id}</title>
23	<style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Courier New',monospace;font-size:13px;padding:10px;max-width:300px;margin:0 auto;color:#000}.c{text-align:center}.big{font-size:26px;font-weight:900;text-align:center;letter-spacing:2px;margin:6px 0}hr{border:none;border-top:1px dashed #000;margin:6px 0}.item{display:flex;gap:6px;padding:2px 0}.qty{font-weight:900;min-width:24px}.addr{font-size:12px;line-height:1.5}.bold{font-weight:700}#bc{display:block;margin:6px auto 2px;max-width:260px}@media print{button{display:none!important}}</style>
24	</head><body>
25	<div class="c bold" style="font-size:11px;letter-spacing:1px">FICHA DE ENTREGA</div>
26	<div class="c" style="font-size:12px">${restauranteNome ?? ''}</div>
27	<div class="big">PEDIDO #${pedido.id}</div>
28	<div class="c" style="font-size:11px">${hora}</div>
29	<hr/>
30	<div class="bold">${cliente?.name ?? 'Cliente'}</div>
31	${cliente?.phone_e164 ? `<div>${cliente.phone_e164}</div>` : ''}
32	<div class="addr" style="margin-top:4px">${rua ? `<div>${rua}</div>` : ''}${compl ? `<div>${compl}</div>` : ''}${cidade ? `<div>${cidade}</div>` : ''}${ref ? `<div style="font-weight:bold">Ref: ${ref}</div>` : ''}</div>
33	<hr/>
34	${itens.map((i) => `<div class="item"><span class="qty">${i.quantity}x</span><span>${i.product_name ?? `#${i.product_id}`}</span></div>`).join('')}
35	<hr/>
36	<div class="c bold" style="font-size:16px">TOTAL: ${fmt(pedido.total)}</div>
37	<div class="c">${isCash ? '<span style="font-size:13px;font-weight:bold">⚠ COBRAR NA ENTREGA</span>' : `Pago: ${pgto}`}</div>
38	<hr/>
39	<svg id="bc"></svg>
40	<div class="c" style="font-size:10px;letter-spacing:1px;margin-top:2px">ESCANEIE PARA CONFIRMAR COLETA</div>
41	<div class="c" style="font-size:10px;margin-top:6px">Impresso: ${new Date().toLocaleString('pt-BR')}</div>
42	<script>
43	function doBarcode(){
44	  if(typeof JsBarcode!=='undefined'){
45	    JsBarcode("#bc","${bc}",{format:"CODE128",width:2,height:56,displayValue:true,fontSize:13,text:"#${pedido.id}",margin:6,background:"#ffffff"});
46	  }
47	  window.print();
48	  setTimeout(()=>{try{window.frameElement.parentNode.removeChild(window.frameElement)}catch(e){}},2000);
49	}
50	var s=document.createElement('script');
51	s.src='https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js';
52	s.onload=doBarcode;
53	s.onerror=function(){document.getElementById('bc').style.display='none';doBarcode()};
54	document.head.appendChild(s);
55	</script>
56	</body></html>`;
57	  printIframe(html, `motoboy-frame-${pedido.id}-${Date.now()}`);
58	};
