60	export const barcodeValue = (id) => String(id).padStart(8, '0');
61	
62	export const getPrinterName = () => localStorage.getItem('kitchen_printer_name') ?? '';
63	export const setPrinterName = (name) => localStorage.setItem('kitchen_printer_name', name);
64	
65	const showPrinterToast = (printerName) => {
66	  const existing = document.getElementById('printer-toast');
67	  if (existing) existing.remove();
68	  const toast = document.createElement('div');
69	  toast.id = 'printer-toast';
70	  toast.innerHTML = `🖨️ Selecione <strong>"${printerName}"</strong> na caixa de impressão`;
71	  toast.style.cssText = 'position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:#1A1A1A;color:#FFD700;padding:12px 22px;border-radius:14px;font-size:14px;font-weight:600;z-index:99999;box-shadow:0 4px 24px rgba(0,0,0,0.6);white-space:nowrap';
72	  document.body.appendChild(toast);
73	  setTimeout(() => toast.remove(), 5000);
74	};
