90	  const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Comanda #${pedido.id}</title>
91	<style>
92	*{margin:0;padding:0;box-sizing:border-box}
93	body{font-family:'Courier New',monospace;font-size:14px;padding:12px;color:#000;max-width:300px;margin:0 auto}
94	.center{text-align:center;display:block}
95	.big{font-size:30px;font-weight:900;text-align:center;letter-spacing:3px;margin:8px 0}
96	.rest{font-size:16px;font-weight:bold;text-align:center;margin-bottom:4px}
97	hr{border:none;border-top:1px dashed #000;margin:8px 0}
