120	<div class="foot">Impresso: ${new Date().toLocaleString('pt-BR')}</div>
121	<script>
122	function doBarcode(){
123	  if(typeof JsBarcode!=='undefined'){
124	    JsBarcode("#barcode","${bc}",{format:"CODE128",width:2,height:56,displayValue:true,fontSize:13,text:"#${pedido.id}",margin:6,background:"#ffffff"});
125	  }
126	  window.print();
127	  try{window.frameElement.parentNode.removeChild(window.frameElement)}catch(e){}
128	}
129	var s=document.createElement('script');
130	s.src='https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js';
131	s.onload=doBarcode;
132	s.onerror=function(){document.getElementById('barcode').style.display='none';doBarcode()};
133	document.head.appendChild(s);
134	</script>
135	</body></html>`;
136	
137	  // Use hidden iframe — no popup blocker, works from setInterval
138	  const frameId = `comanda-frame-${pedido.id}-${Date.now()}`;
139	  const iframe = document.createElement('iframe');
140	  iframe.id = frameId;
141	  iframe.style.cssText = 'position:fixed;bottom:-1px;left:-1px;width:1px;height:1px;border:0;opacity:0;pointer-events:none';
142	  document.body.appendChild(iframe);
143	
144	  try {
145	    iframe.contentDocument.open();
146	    iframe.contentDocument.write(html);
147	    iframe.contentDocument.close();
